mapper.select:
SELECT c.*, i.title AS item_title, i.type AS item_type, i.publisher_openid
FROM `claim` c
LEFT JOIN `item` i ON c.item_id = i.id
WHERE c.claimant_openid = #{claimantOpenid}
ORDER BY c.create_time DESC
LIMIT #{offset}, #{size}

SELECT c.*, i.title AS item_title, i.type AS item_type, i.publisher_openid
FROM `claim` c
LEFT JOIN `item` i ON c.item_id = i.id
WHERE i.publisher_openid = #{publisherOpenid}
ORDER BY c.create_time DESC
LIMIT #{offset}, #{size}

mapper.update:
UPDATE `claim`
SET status = 2, update_time = NOW()
WHERE item_id = #{itemId}
  AND status = 0
  AND id != #{excludeId}
